CREATE TABLE "ReferenceDataset"(id text PRIMARY KEY,kind text NOT NULL CHECK(kind IN('fund','newspaper')),title text NOT NULL,"sourceSha256" text NOT NULL,"importHash" text NOT NULL,source jsonb NOT NULL,"isPublic" boolean NOT NULL DEFAULT false,"createdAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "ReferenceDataset_kind_isPublic_id_idx" ON "ReferenceDataset"(kind,"isPublic",id);
CREATE TABLE "ReferenceEntry"(id text PRIMARY KEY,"datasetId" text NOT NULL REFERENCES "ReferenceDataset"(id),"sourceKey" text NOT NULL,position integer NOT NULL,number text,title text NOT NULL,"searchText" text NOT NULL,payload jsonb NOT NULL,raw jsonb NOT NULL,"isPublic" boolean NOT NULL DEFAULT false,UNIQUE("datasetId","sourceKey"));
CREATE INDEX "ReferenceEntry_datasetId_isPublic_position_id_idx" ON "ReferenceEntry"("datasetId","isPublic",position,id);
CREATE INDEX "ReferenceEntry_isPublic_title_id_idx" ON "ReferenceEntry"("isPublic",title,id);
CREATE INDEX "ReferenceEntry_number_idx" ON "ReferenceEntry"(number);
CREATE TABLE "CmsAttachment"(id text PRIMARY KEY,"revisionId" text NOT NULL REFERENCES "ContentRevision"(id) ON DELETE CASCADE,"parentId" text,variant text NOT NULL DEFAULT 'master' CHECK(variant IN('master','preview')),state text NOT NULL DEFAULT 'AWAITING_CONTENT' CHECK(state IN('AWAITING_CONTENT','RECEIVING','QUARANTINED','APPROVED','PUBLISHED','REJECTED','FAILED','WITHDRAWN')),name text NOT NULL,"mimeType" text NOT NULL,"expectedBytes" integer NOT NULL CHECK("expectedBytes">0 AND "expectedBytes"<=20971520),"expectedSha256" text NOT NULL,"storageKey" text UNIQUE,parsed jsonb,"previewKey" text,"previewSha256" text,"previewBytes" integer,rights text NOT NULL,"sourceNote" text NOT NULL,"sourceLabel" text NOT NULL,"sourceVersion" text NOT NULL,"uploaderId" text NOT NULL,"reviewerId" text,"failureCode" text,"receiveToken" text,"createdAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK("reviewerId" IS NULL OR "reviewerId"<>"uploaderId"));
CREATE INDEX "CmsAttachment_revisionId_state_id_idx" ON "CmsAttachment"("revisionId",state,id);
CREATE TABLE "RealContentBinding"(id text PRIMARY KEY,namespace text NOT NULL,"sourceKey" text NOT NULL,locale text NOT NULL,"targetKind" text NOT NULL,"targetId" text NOT NULL,"inputHash" text NOT NULL,"outputHash" text NOT NULL,data jsonb NOT NULL,"createdAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(namespace,"sourceKey",locale));
